package dev.bennett.codexmeter;
import android.app.*;import android.content.*;import android.os.*;import android.view.*;import android.widget.*;import org.json.*;
/** Actual adaptive goal screen plus read-only rendering of today-done and paused states. */
public final class Beta997GoalUiNativeTest extends Instrumentation {
    int checks;Throwable failure;String locale,theme;
    void check(boolean value,String message){checks++;if(!value)throw new AssertionError(message);}
    void main(Runnable action){runOnMainSync(()->{try{action.run();}catch(Throwable t){failure=t;}});if(failure!=null){Throwable problem=failure;failure=null;throw new AssertionError(problem);}}
    void bounds(View view){if(view==null||view.getVisibility()!=View.VISIBLE)return;if(view instanceof TextView){TextView t=(TextView)view;if(t.getLayout()!=null&&t.length()>0){android.text.Layout layout=t.getLayout();check(layout.getEllipsisCount(layout.getLineCount()-1)==0,"No truncated text");check(t.getHeight()+1>=t.getCompoundPaddingTop()+t.getCompoundPaddingBottom()+layout.getLineBottom(layout.getLineCount()-1),"No vertically clipped text");}if(view instanceof Button)check(view.getHeight()+1>=48*view.getResources().getDisplayMetrics().density,"48dp action target");}if(view instanceof android.view.ViewGroup)for(int i=0;i<((android.view.ViewGroup)view).getChildCount();i++)bounds(((android.view.ViewGroup)view).getChildAt(i));}
    @Override public void onCreate(Bundle args){super.onCreate(args);locale=args.getString("locale","ko");theme=args.getString("theme","dark");start();}
    @Override public void onStart(){Bundle result=new Bundle();int code=0;Context c=getTargetContext();GrowthActivity screen=null;String oldTheme=AppPreferences.getAppTheme(c);android.app.LocaleManager locales=c.getSystemService(android.app.LocaleManager.class);String oldLocale=locales.getApplicationLocales().toLanguageTags();try{
        check(Build.MODEL.contains("sdk")&&c.getPackageName().equals("dev.bennett.codexmeter.trial")&&TrialDemo.active(c),"Owned synthetic beta only");
        String account=SubscriptionStore.accountKey(c);JSONObject before=BetaGrowthStore.load(c,account);long xp=before.getLong("total");AppPreferences.setAppTheme(c,theme);locales.setApplicationLocales(android.os.LocaleList.forLanguageTags(locale));Thread.sleep(500);
        screen=(GrowthActivity)startActivitySync(new Intent(c,GrowthActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));GrowthActivity a=screen;
        for(int i=0;i<70;i++){final boolean[] ready={false};main(()->ready[0]=a.findViewById(android.R.id.content).findViewWithTag("beta997:next-goal")!=null);if(ready[0])break;Thread.sleep(100);}waitForIdleSync();Thread.sleep(200);
        check(a.getResources().getConfiguration().getLocales().get(0).getLanguage().equals(locale),"Requested KO/EN locale actually applied");check(Ui.isDark(a)==theme.equals("dark"),"Requested theme actually applied");
        main(()->{View root=a.findViewById(android.R.id.content),goal=root.findViewWithTag("beta997:next-goal"),hero=root.findViewWithTag("beta:hero");check(goal!=null&&goal.isShown(),"Actual next-goal card shown");android.view.ViewGroup parent=(android.view.ViewGroup)goal.getParent();check(parent.indexOfChild(goal)<parent.indexOfChild(hero),"Next goal precedes detailed level card");check(root.findViewWithTag("beta997:goal-details")!=null,"Goal condition action present");bounds(goal);bounds(root.findViewWithTag("matte_bottom"));});
        JSONObject completed=new JSONObject(before.toString()).put("enabled",true);long now=System.currentTimeMillis();BetaV4.confirm(completed,account,now,now,true);JSONObject journal=new JSONObject().put("beta_v4",completed);BetaGrowthModel done=BetaGrowthModel.create(journal,account,now,true,false,true);
        main(()->{LinearLayout body=new LinearLayout(a);body.setOrientation(LinearLayout.VERTICAL);BetaNextGoalUi.render(a,body,completed,done,Ui.isDark(a),account);check(body.findViewWithTag("beta997:goal-check")==null,"Completed today never asks for another XP refresh");check(body.findViewWithTag("beta997:goal-details")!=null,"Completed state offers conditions instead");});
        completed.put("enabled",false);BetaGrowthModel paused=BetaGrowthModel.create(journal,account,now,true,false,true);main(()->{LinearLayout body=new LinearLayout(a);BetaNextGoalUi.render(a,body,completed,paused,Ui.isDark(a),account);check(body.findViewWithTag("beta997:goal-check")==null,"Paused collection never asks for XP refresh");});
        java.io.File dir=new java.io.File(c.getExternalFilesDir(null),"beta997-goal-captures");dir.mkdirs();String file=locale+"-"+theme+"-"+a.getResources().getConfiguration().fontScale+".png";try(java.io.FileOutputStream out=new java.io.FileOutputStream(new java.io.File(dir,file))){getUiAutomation().takeScreenshot().compress(android.graphics.Bitmap.CompressFormat.PNG,100,out);}
        check(BetaGrowthStore.load(c,account).getLong("total")==xp,"Views and copied goal simulations give no XP");result.putString("stream","Beta997 goal UI: "+checks+" checks passed; "+locale+" / "+theme+" / font "+a.getResources().getConfiguration().fontScale+"; synthetic only.\n");code=-1;
    }catch(Throwable error){result.putString("stream",android.util.Log.getStackTraceString(error));}finally{if(screen!=null){GrowthActivity a=screen;main(a::finish);}AppPreferences.setAppTheme(c,oldTheme);locales.setApplicationLocales(android.os.LocaleList.forLanguageTags(oldLocale));}finish(code,result);}
}
